class TrieNode {
    val next = HashMap<Char, TrieNode>()
    var word: String? = null
}

fun findWords(board: Array<CharArray>, words: List<String>): List<String> {
    val root = TrieNode()
    for (w in words) {
        var n = root
        for (c in w) n = n.next.getOrPut(c) { TrieNode() }
        n.word = w
    }
    val res = mutableListOf<String>()
    val dirs = listOf(0 to 1, 0 to -1, 1 to 0, -1 to 0)
    fun dfs(r: Int, c: Int, node: TrieNode) {
        val ch = board[r][c]
        val child = node.next[ch] ?: return
        child.word?.let { res += it; child.word = null }  // dedupe
        board[r][c] = '#'
        for ((dr, dc) in dirs) {
            val nr = r + dr; val nc = c + dc
            if (nr in board.indices && nc in board[0].indices && board[nr][nc] != '#') {
                dfs(nr, nc, child)
            }
        }
        board[r][c] = ch
    }
    for (r in board.indices) for (c in board[0].indices) dfs(r, c, root)
    return res
}

