class GNode(val value: Int) { val neighbors = mutableListOf<GNode>() }

fun cloneGraph(node: GNode?): GNode? {
    if (node == null) return null
    val seen = HashMap<GNode, GNode>()
    fun clone(n: GNode): GNode {
        seen[n]?.let { return it }
        val copy = GNode(n.value)
        seen[n] = copy
        for (nb in n.neighbors) copy.neighbors += clone(nb)
        return copy
    }
    return clone(node)
}

