fun ladderLength(begin: String, end: String, wordList: List<String>): Int {
    val words = wordList.toHashSet()
    if (end !in words) return 0
    val q = ArrayDeque<String>()
    q.add(begin)
    var dist = 1
    while (q.isNotEmpty()) {
        repeat(q.size) {
            val w = q.removeFirst()
            if (w == end) return dist
            val chars = w.toCharArray()
            for (i in chars.indices) {
                val orig = chars[i]
                for (c in 'a'..'z') {
                    chars[i] = c
                    val nxt = String(chars)
                    if (words.remove(nxt)) q.addLast(nxt)  // remove = visited
                }
                chars[i] = orig
            }
        }
        dist++
    }
    return 0
}

