fun networkDelayTime(times: List<IntArray>, n: Int, k: Int): Int {
    val adj = HashMap<Int, MutableList<Pair<Int, Int>>>()
    for ((u, v, w) in times) adj.getOrPut(u) { mutableListOf() } += v to w
    val dist = IntArray(n + 1) { Int.MAX_VALUE }
    dist[k] = 0
    val pq = java.util.PriorityQueue<Pair<Int, Int>>(compareBy { it.second })  // (node, dist)
    pq.add(k to 0)
    while (pq.isNotEmpty()) {
        val (u, d) = pq.poll()
        if (d > dist[u]) continue   // stale entry
        for ((v, w) in adj[u] ?: emptyList()) {
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w
                pq.add(v to dist[v])
            }
        }
    }
    val max = dist.drop(1).max()
    return if (max == Int.MAX_VALUE) -1 else max
}

