fun findOrder(numCourses: Int, prerequisites: Array<IntArray>): IntArray {
    val adj = Array(numCourses) { mutableListOf<Int>() }
    val indeg = IntArray(numCourses)
    for ((a, b) in prerequisites) { adj[b] += a; indeg[a]++ }
    val q = ArrayDeque<Int>()
    indeg.indices.filter { indeg[it] == 0 }.forEach { q.addLast(it) }
    val order = mutableListOf<Int>()
    while (q.isNotEmpty()) {
        val u = q.removeFirst()
        order += u
        for (v in adj[u]) if (--indeg[v] == 0) q.addLast(v)
    }
    return if (order.size == numCourses) order.toIntArray() else intArrayOf()
}

