fun findRedundantConnection(edges: Array<IntArray>): IntArray {
    val parent = IntArray(edges.size + 1) { it }
    fun find(x: Int): Int {
        var r = x
        while (parent[r] != r) r = parent[r]
        var cur = x
        while (parent[cur] != r) { val nxt = parent[cur]; parent[cur] = r; cur = nxt }
        return r
    }
    for ((a, b) in edges) {
        val ra = find(a); val rb = find(b)
        if (ra == rb) return intArrayOf(a, b)
        parent[ra] = rb
    }
    return intArrayOf()
}

