fun solveNQueens(n: Int): List<List<String>> {
    val cols = BooleanArray(n)
    val diag = HashSet<Int>()
    val anti = HashSet<Int>()
    val board = Array(n) { CharArray(n) { '.' } }
    val res = mutableListOf<List<String>>()
    fun place(r: Int) {
        if (r == n) { res += board.map { it.joinToString("") }; return }
        for (c in 0 until n) {
            val d = r - c; val a = r + c
            if (cols[c] || d in diag || a in anti) continue
            board[r][c] = 'Q'; cols[c] = true; diag += d; anti += a
            place(r + 1)
            board[r][c] = '.'; cols[c] = false; diag.remove(d); anti.remove(a)
        }
    }
    place(0)
    return res
}

